var age = Math.max(0, +v('age') || 0), leave = Math.max(0, +v('leave') || 0);
var ry = Math.max(0, leave - age), left = Math.round(ry * 365), total = Math.round(Math.max(leave, age) * 365);
if (total < 1) { if (el._crowdStop) el._crowdStop(); el.innerHTML = ''; return; }
left = Math.min(total, left);
Crowd.units(el, { total: total, used: total - left, unit: '日',
title: '巣立ちまでの毎日を玉で並べると',
final: function (l) { return 'のこり ' + l.toLocaleString('ja-JP') + '日、夏休みはあと ' + ry + '回。一緒にいる時間は小さいころほど長く、日数よりも早く過ぎていきます。'; } });
